import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.vLhlLNVn.js";const b=JSON.parse('{"title":"Wie schalte ich das ESPHome-Dashboard ein und öffne es?","description":"","frontmatter":{"order":4,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/01.erste-schritte/04.dashboard-einschalten.md"},"headers":[],"relativePath":"de/adapter/esphome/erste-schritte/dashboard-einschalten.md","filePath":"de/adapter/esphome/erste-schritte/dashboard-einschalten.md","lastUpdated":null}'),i={name:"de/adapter/esphome/erste-schritte/dashboard-einschalten.md"};function s(d,e,o,h,l,c){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="wie-schalte-ich-das-esphome-dashboard-ein-und-offne-es" tabindex="-1">Wie schalte ich das ESPHome-Dashboard ein und öffne es? <a class="header-anchor" href="#wie-schalte-ich-das-esphome-dashboard-ein-und-offne-es" aria-label="Permalink to &quot;Wie schalte ich das ESPHome-Dashboard ein und öffne es?&quot;">​</a></h1><p><a id="dashboard-tab-not-open-localhost"></a></p><h2 id="warum-offnet-sich-der-dashboard-tab-nicht-localhost-verweigert-die-verbindung" tabindex="-1">Warum öffnet sich der Dashboard-Tab nicht (&quot;localhost verweigert die Verbindung&quot;)? <a class="header-anchor" href="#warum-offnet-sich-der-dashboard-tab-nicht-localhost-verweigert-die-verbindung" aria-label="Permalink to &quot;Warum öffnet sich der Dashboard-Tab nicht (&quot;localhost verweigert die Verbindung&quot;)?&quot;">​</a></h2><p>Trag bei „IP-Adresse, unter der ESPHome Dashboard zur Integration in ioBroker Admin ausgeführt wird“ die Adresse deines ioBroker-Rechners ein, ohne Port. Nimm nicht <code>localhost</code> oder <code>127.0.0.1</code>.</p><p>Der Tab zeigt die Seite unter „URL des ESPHome-Dashboards“. Diese Seite lädt dein Browser, nicht der ioBroker-Rechner. <code>localhost</code> zeigt deshalb auf den Rechner, an dem du sitzt, und der Browser meldet „localhost verweigert die Verbindung“.</p><h3 id="so-gehst-du-vor" tabindex="-1">So gehst du vor <a class="header-anchor" href="#so-gehst-du-vor" aria-label="Permalink to &quot;So gehst du vor&quot;">​</a></h3><ol><li>Öffne die Instanz-Einstellungen, Reiter „ESPHome-Dashboard“.</li><li>Setze den Haken bei „ESPHome-Dashboard aktivieren“.</li><li>Wähle im IP-Feld eine Adresse des ioBroker-Rechners aus der Liste. Die Liste bietet IPv4- und IPv6-Adressen an, ein Hostname geht auch. Schreib keinen Port dazu, den hängt der Adapter selbst an.</li><li>Unter „Fortschrittlich“ steht der „Port des ESPHome-Dashboards“, Standard <code>6052</code>. Darunter füllt sich „URL des ESPHome-Dashboards“ von selbst, z. B. <code>http://192.168.x.y:6052</code>. Eine eigene URL trägst du zuletzt ein, weil eine Änderung an IP oder Port sie wieder überschreibt.</li><li>Speichere. Die Instanz startet neu.</li><li>Öffne den ESPHome-Tab im Admin-Menü. Während das Dashboard startet, zeigt er einen Hinweis und das Startprotokoll. Sobald das Dashboard antwortet, erscheint es von selbst. Beim ersten Start dauert das einige Minuten.</li></ol><p>Zeigt der Tab statt des Dashboards einen Text, steht dort der Grund: Instanz läuft nicht, Dashboard nicht aktiviert, keine URL eingetragen oder Start fehlgeschlagen. Im letzten Fall hilft <a href="./../fehlerbehebung/dashboard-startet-nicht#dashboard-not-start-pillow-esphome">Warum startet das Dashboard nicht?</a>.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/dashboard-nutzen#show-dashboard-admin-tab-using">Wie zeige ich das Dashboard im Admin-Tab bei HTTPS an?</a></p><p><a id="flash-device-first-time-if"></a></p><h2 id="wie-flashe-ich-ein-gerat-zum-ersten-mal-wenn-der-server-keinen-usb-zugang-hat" tabindex="-1">Wie flashe ich ein Gerät zum ersten Mal, wenn der Server keinen USB-Zugang hat? <a class="header-anchor" href="#wie-flashe-ich-ein-gerat-zum-ersten-mal-wenn-der-server-keinen-usb-zugang-hat" aria-label="Permalink to &quot;Wie flashe ich ein Gerät zum ersten Mal, wenn der Server keinen USB-Zugang hat?&quot;">​</a></h2><p>Das erste Flashen braucht eine Kabelverbindung zum Gerät. Hat der ioBroker-Rechner keinen USB-Zugang, z. B. in einer VM oder einem Container, flashst du vom eigenen PC aus. Danach spielst du Änderungen über WLAN (OTA) aus dem Dashboard des Adapters auf.</p><ol><li>Leg das Gerät im Dashboard an und klick bei „Install“ auf „Manual download“.</li><li>Lade die Firmware herunter.</li><li>Schließ das Gerät per USB an deinen PC an und flashe die Datei mit einem Flash-Tool, z. B. <a href="https://web.esphome.io" target="_blank" rel="noreferrer">ESPHome Web</a>.</li><li>Sobald das Gerät im WLAN ist, wählst du bei „Install“ den Weg „Wirelessly“.</li></ol><p>„Plug into this computer“ im Dashboard funktioniert nur, wenn du das Dashboard über HTTPS öffnest.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/dashboard-nutzen#show-dashboard-admin-tab-using">Dashboard bei HTTPS anzeigen</a></p>',15)])])}const m=a(i,[["render",s]]);export{b as __pageData,m as default};
